// Parse the JSON response body
const responseData = pm.response.json();

// Verify the response is an array before iterating
if (Array.isArray(responseData)) {
    responseData.forEach(org => {
        // Ensure both code and id exist to avoid setting undefined variables
        if (org.code && org.id) {
            // Set the environment variable using the code as the key and id as the value
            pm.environment.set(org.code, org.id);
        }
    });
    console.log("Organization variables successfully set in the environment.");
} else {
    console.error("Expected response to be an array of organizations.");
}

// Parse the JSON response
const response = pm.response.json();

// Loop through each object in the array
response.forEach(module => {
    // Check if both properties exist to avoid errors
    if (module.code && module.id) {
        // Set as a collection variable (e.g., key: "CORE", value: "118744f5...")
        pm.environment.set(module.code, module.id);
    }
});

// Optional: Log confirmation to the Postman console
console.log("Modules mapped and saved as collection variables.");

